components.css:
.research-areas-page { width: var(--shell); margin: 0 auto; padding-bottom: var(--space-page); }
.areas-masthead { padding: clamp(40px, 5vw, 72px) 0 clamp(32px, 4vw, 52px); }
.areas-masthead h1 { margin: 0; font-size: clamp(38px, 4.8vw, 66px); font-weight: 600; letter-spacing: -.035em; line-height: 1.1; }
.areas-masthead > p { max-width: 66ch; margin: 20px 0 0; color: var(--ink-soft); font-size: clamp(18px, 1.5vw, 20px); line-height: 1.6; }
.areas-guide { border-top: 1px solid var(--ink); }
.areas-field { border-bottom: 1px solid var(--rule-strong); }
.areas-field summary { display: grid; grid-template-columns: minmax(0, 1fr) 28px; align-items: start; gap: 24px; padding: 26px 0; list-style: none; cursor: pointer; }
.areas-field summary::-webkit-details-marker { display: none; }
.areas-field summary::marker { content: ""; }
.areas-field summary h2 { max-width: 35ch; margin: 0; font-size: clamp(25px, 2.7vw, 36px); font-weight: 500; line-height: 1.2; letter-spacing: -.025em; }
.areas-field summary p { max-width: 73ch; margin: 10px 0 0; color: var(--ink-soft); font-size: 16px; line-height: 1.6; }
.areas-field summary:hover h2 { color: var(--red); }
.areas-disclosure { display: flex; align-items: center; justify-content: center; width: 28px; height: 28px; margin-top: 3px; color: var(--red); }
.areas-disclosure svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.5; }
.areas-disclosure-vertical { transform-origin: center; transition: transform var(--dur-2) var(--ease-out); }
.areas-field[open] .areas-disclosure-vertical { transform: rotate(90deg); }
.areas-field-body { display: grid; grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr); gap: 26px 48px; margin-left: clamp(0px, 8vw, 120px); padding: 6px 52px 32px 0; }
.areas-field-body h3 { margin: 0 0 14px; color: var(--slate); font-family: var(--sans); font-size: 14px; font-weight: 600; line-height: 1.5; letter-spacing: 0; }
.areas-field-body ul { margin: 0; padding: 0; list-style: none; }
.areas-questions li { max-width: 45ch; color: var(--ink); font-size: 18px; line-height: 1.6; }
.areas-questions li + li { margin-top: 12px; }
.areas-evidence li { color: var(--ink-soft); font-size: 16px; line-height: 1.6; }
.areas-evidence li + li { margin-top: 10px; }
.areas-publications { grid-column: 1 / -1; display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 24px; padding-top: 18px; border-top: 1px solid var(--rule); }
.areas-publications > p { margin: 0; color: var(--slate); font-size: 14px; line-height: 1.6; }
.areas-link { display: inline-flex; align-items: center; gap: 10px; min-height: 44px; padding: 7px 0; color: var(--red); font-size: 15px; font-weight: 600; line-height: 1.45; text-decoration: underline; text-underline-offset: 5px; }
.areas-link svg { width: 16px; height: 16px; flex: 0 0 16px; }
.areas-link:hover { color: var(--red-dark); text-decoration-thickness: 2px; }
.areas-footer { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 8px 32px; padding-top: 28px; }
.areas-footer > p { margin: 0; color: var(--ink-soft); font-size: 17px; line-height: 1.6; }
@media (max-width: 760px) {
  .areas-field-body { grid-template-columns: minmax(0, 1fr); gap: 24px; margin-left: 0; }
  .areas-publications { grid-column: 1; }
}
@media (max-width: 640px) {
  .areas-masthead { padding-top: 32px; }
  .areas-masthead h1 { font-size: clamp(35px, 8.6vw, 49px); }
  .areas-field summary { gap: 16px; padding: 24px 0; }
  .areas-field summary h2 { font-size: 26px; }
  .areas-field-body { padding-right: 0; }
  .areas-publications { gap: 0 20px; }
}

.ds-home-masthead{font-family:var(--sans,'Schibsted Grotesk','Helvetica Neue',Arial,sans-serif)}.ds-home-hero-stage h1{font-family:var(--display,'Space Grotesk','Helvetica Neue',Arial,sans-serif);color:var(--ink,#151515)}.ds-button-primary,.ds-text-link{display:inline-flex;align-items:center;justify-content:center;gap:14px;font-weight:600;line-height:1.25;text-decoration:none;transition:background var(--dur-1,150ms) var(--ease-out,cubic-bezier(.16,1,.3,1)),color var(--dur-1,150ms) var(--ease-out,cubic-bezier(.16,1,.3,1)),border-color var(--dur-1,150ms) var(--ease-out,cubic-bezier(.16,1,.3,1))}.ds-button-primary{border:1px solid var(--red,#782c3d);background:var(--red,#782c3d);color:var(--on-dark,#fff)}.ds-button-primary:hover{background:var(--red-dark,#55202c);border-color:var(--red-dark,#55202c)}.ds-text-link{padding:12px 0;border-bottom:1px solid var(--rule-dark,rgba(255,255,255,.23))}.ds-button-primary svg,.ds-text-link svg{width:18px;height:18px;flex:none;transition:transform var(--dur-2,250ms) var(--ease-out,cubic-bezier(.16,1,.3,1))}.ds-button-primary:hover svg,.ds-text-link:hover svg{transform:translateX(4px)}.ds-home-masthead a:focus-visible{outline:2px solid var(--focus-on-dark,#ecc0c9);outline-offset:3px}.ds-home-masthead { margin: 0 0 48px; }
.ds-home-hero-stage { position: relative; width: var(--shell,min(1440px, calc(100% - 40px))); margin: 0 auto; padding: clamp(40px, 4.2vw, 64px) 0 clamp(48px, 5.5vw, 80px); }
.ds-home-hero-stage h1 { position: relative; z-index: 1; margin: 0; font-size: clamp(100px, 16.5vw, 248px); font-weight: 650; letter-spacing: -.04em; line-height: .94; text-wrap: nowrap; }
.ds-home-title-line { display: flex; overflow: clip; padding: .03em 0 .06em; }
.ds-home-title-line-canada { justify-content: flex-end; }
.ds-home-title-word { display: block; }
.ds-home-hero-slash { position: absolute; left: 8%; bottom: clamp(58px, 6.5vw, 96px); width: clamp(44px, 5.8vw, 86px); height: clamp(100px, 15vw, 224px); }
.ds-home-hero-slash span { display: block; width: 100%; height: 100%; background: var(--red,#782c3d); transform: skewX(-18deg); transform-origin: 50% 100%; }
.ds-home-hero-band { background: var(--soft-black,#151515); color: var(--on-dark,#fff); }
.ds-home-hero-band-inner { width: var(--shell,min(1440px, calc(100% - 40px))); margin: 0 auto; padding: 32px 0; display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 32px clamp(32px, 6vw, 96px); }
.ds-home-hero-band-inner > p { max-width: 44ch; margin: 0; color: var(--on-dark-soft,#e2d9dc); font-size: clamp(18px, 1.55vw, 22px); line-height: 1.5; text-wrap: pretty; }
.ds-home-masthead-actions { display: flex; flex-wrap: wrap; align-items: center; justify-content: flex-end; gap: 12px 24px; }
.ds-home-masthead-actions .ds-button-primary { min-height: 56px; padding: 16px 24px; font-size: 16px; }
.ds-home-masthead-actions .ds-text-link { min-height: 48px; font-size: 15px; color: var(--on-dark,#fff); border-color: var(--rule-dark,rgba(255,255,255,.23)); }
.ds-home-masthead-actions :is(a, button):focus-visible { outline-color: var(--focus-on-dark,#ecc0c9); }
.ds-home-masthead-actions .ds-text-link:hover { color: var(--on-dark-soft,#e2d9dc); border-color: var(--on-dark,#fff); }
@media (prefers-reduced-motion: no-preference) {
  .ds-home-title-word { animation: home-type-enter 900ms var(--ease-out,cubic-bezier(.16,1,.3,1)) both; }
  .ds-home-title-line-canada .ds-home-title-word { animation-name: home-type-return; animation-delay: 120ms; }
  .ds-home-hero-slash span { animation: home-slash-unfold 1100ms var(--ease-out,cubic-bezier(.16,1,.3,1)) 180ms both; }
}
@keyframes home-type-enter { from { clip-path: inset(0 100% 0 0); transform: translateX(-32px); } to { clip-path: inset(0); transform: translateX(0); } }
@keyframes home-type-return { from { clip-path: inset(0 0 0 100%); transform: translateX(32px); } to { clip-path: inset(0); transform: translateX(0); } }
@keyframes home-slash-unfold { from { transform: skewX(-18deg) scaleY(.08); } to { transform: skewX(-18deg) scaleY(1); } }
@media (max-width: 1050px) {
  .ds-home-hero-band-inner { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 32px; }
  .ds-home-masthead-actions { justify-content: flex-start; gap: 8px 20px; }
}
@media (max-width: 760px) {
  .ds-home-masthead { margin-bottom: 32px; }
  .ds-home-hero-stage { padding: 36px 0 44px; }
  .ds-home-hero-stage h1 { font-size: clamp(76px, 16.5vw, 124px); }
  .ds-home-hero-slash { left: 7%; bottom: 52px; width: 6vw; height: 15vw; }
  .ds-home-hero-band-inner { grid-template-columns: minmax(0, 1fr); gap: 24px; padding: 28px 0; }
  .ds-home-hero-band-inner > p { max-width: 42ch; font-size: 18px; }
  .ds-home-masthead-actions { justify-content: flex-start; }
}
@media (max-width: 480px) {
  .ds-home-hero-stage { padding: 32px 0 36px; }
  .ds-home-hero-stage h1 { font-size: clamp(64px, 17.7vw, 84px); }
  .ds-home-title-line-canada { margin-top: 8px; }
  .ds-home-hero-slash { left: 8%; bottom: 44px; width: 20px; height: 56px; }
  .ds-home-hero-band-inner { padding: 24px 0; gap: 20px; }
  .ds-home-hero-band-inner > p { font-size: 17px; }
  .ds-home-masthead-actions { align-items: flex-start; flex-direction: column; gap: 12px; }
  .ds-home-masthead-actions .ds-button-primary { padding: 14px 18px; font-size: 15px; }
}
@media(prefers-reduced-motion:reduce){.ds-button-primary,.ds-text-link,.ds-button-primary svg,.ds-text-link svg{transition:none}}

.ds-home-explore{font-family:var(--sans,'Schibsted Grotesk','Helvetica Neue',Arial,sans-serif)}.ds-home-explore a:focus-visible{outline:2px solid var(--focus,#782c3d);outline-offset:3px}.ds-home-explore { width: var(--shell,min(1440px, calc(100% - 40px))); margin: 0 auto; padding: 0 0 clamp(48px, 6vw, 80px); display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }
.ds-home-explore > a { min-height: 88px; padding: 20px 24px; display: flex; align-items: center; justify-content: space-between; gap: 24px; border: 1px solid var(--rule-strong,rgba(21,21,21,.35)); color: var(--ink,#151515); background: var(--ivory,#fff); font-family: var(--display,'Space Grotesk','Helvetica Neue',Arial,sans-serif); font-size: clamp(18px, 1.6vw, 23px); font-weight: 550; line-height: 1.3; text-decoration: none; transition: background var(--dur-2,250ms) var(--ease-out,cubic-bezier(.16,1,.3,1)), border-color var(--dur-2,250ms) var(--ease-out,cubic-bezier(.16,1,.3,1)); }
.ds-home-explore > a svg { flex: none; width: 22px; height: 22px; color: var(--red,#782c3d); transition: transform var(--dur-2,250ms) var(--ease-out,cubic-bezier(.16,1,.3,1)); }
.ds-home-explore > a:hover { background: var(--ivory-deep,#f3f3f2); border-color: var(--ink,#151515); }
.ds-home-explore > a:hover svg { transform: translateX(4px); }
@media (max-width: 760px) {
  .ds-home-explore { gap: 12px; }
  .ds-home-explore > a { min-height: 96px; padding: 16px; gap: 12px; font-size: 18px; }
}
@media (max-width: 480px) {
  .ds-home-explore { grid-template-columns: minmax(0, 1fr); }
  .ds-home-explore > a { min-height: 76px; }
}
@media(prefers-reduced-motion:reduce){.ds-home-explore a,.ds-home-explore a svg{transition:none}}
